// Verificar se há alguma discussão ou exceção sobre prazo em dobro em processos eletrônicos
// Procurando por artigos que possam contradizer ou complementar o art. 229 §2º

const fs = require('fs');
const path = require('path');

// Ler todos os arquivos da biblioteca
const libraryPath = '/work/library';
const files = fs.readdirSync(libraryPath);

for (const file of files) {
  if (file.endsWith('.md')) {
    const filePath = path.join(libraryPath, file);
    const content = fs.readFileSync(filePath, 'utf8');
    // Procurar por menções a prazo em dobro, processos eletrônicos ou exceções
    if (content.toLowerCase().includes('prazo em dobro') || 
        content.toLowerCase().includes('processo eletrônico') ||
        content.toLowerCase().includes('exceto') ||
        content.toLowerCase().includes('exceção')) {
      console.log(`\n=== ${file} ===`);
      console.log(content);
    }
  }
}

