// Ler todos os arquivos da biblioteca e buscar por menções a jurisprudência ou súmulas
const fs = require('fs');
const path = require('path');

const libraryPath = '/work/library';
const files = fs.readdirSync(libraryPath);

console.log('Buscando por menções a jurisprudência ou súmulas na biblioteca:\n');

let foundAny = false;
for (const file of files) {
  if (file.endsWith('.md')) {
    const filePath = path.join(libraryPath, file);
    const content = fs.readFileSync(filePath, 'utf8');
    const mentions = content.match(/(STJ|STF|TJSP|jurisprudência|súmula)/gi);
    if (mentions && mentions.length > 0) {
      console.log(`\n${file}:`);
      const lines = content.split('\n');
      for (const line of lines) {
        if (line.match(/(STJ|STF|TJSP|jurisprudência|súmula)/i)) {
          console.log(line.trim());
        }
      }
      foundAny = true;
    }
  }
}

if (!foundAny) {
  console.log('Nenhuma menção a jurisprudência ou súmulas encontrada na biblioteca.');
}

